    chooseProvider(key: string) { if (this.busy || this.reviewOpen || !this.draft.find(row => row.key === key)?.isAvailable) return; this.draft.forEach(row => { row.isEnabled = row.key === key }) },
    providerKey(event: KeyboardEvent, key: string) { const keys = this.draft.filter(row => row.isAvailable).map(row => row.key); if (this.busy || this.reviewOpen || !keys.length || !['ArrowDown', 'ArrowRight', 'ArrowUp', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const index = event.key === 'Home' ? 0 : event.key === 'End' ? keys.length - 1 : (keys.indexOf(key) + (['ArrowDown', 'ArrowRight'].includes(event.key) ? 1 : -1) + keys.length) % keys.length; const group = (event.currentTarget as HTMLElement | null)?.parentElement; this.chooseProvider(keys[index]!); this.$nextTick(() => group?.querySelector<HTMLElement>('[aria-checked="true"]:not(:disabled)')?.focus()) },
    setSection(key: string) { this.section = key; void this.$router.replace({ query: this.$route.query, hash: '#' + key }); if (key === 'moderation' && !this.inventory) void this.loadInventory(); if (key === 'closed') { if (!this.closedInventory) void this.loadClosed(); if (!this.pages.length) void this.loadPages() } },
    tabKey(event: KeyboardEvent, key: string) { const keys = this.tabs.map(tab => tab.key); if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const index = event.key === 'Home' ? 0 : event.key === 'End' ? keys.length - 1 : (keys.indexOf(key) + (event.key === 'ArrowRight' ? 1 : -1) + keys.length) % keys.length; this.setSection(keys[index]!); this.$nextTick(() => document.getElementById('discussion-tab-' + keys[index])?.focus()) },
    resetPolicy() { if (!this.saved || this.busy) return; this.draft = copy(this.saved.providers); this.enabled = this.saved.enabled; this.pageRatingsEnabled = this.saved.pageRatingsEnabled; this.pageRatingsMode = this.saved.pageRatingsMode; this.saveError = '' },
    async reload() { if (this.loading || this.busy || this.disposed || (this.dirty && !(await confirmDiscard(this.$t('admin:comments.discardUnsavedDiscussionPolicy')))) || this.loading || this.busy || this.disposed) return; this.loading = true; this.loadError = ''; try { const value = await fetchDiscussionWorkspace(); if (this.disposed) return; this.saved = value; this.resetPolicy(); this.inventory = null; this.closedInventory = null; this.setSection(this.section) } catch (error) { if (!this.disposed) this.loadError = getErrorMessage(error) } finally { if (!this.disposed) this.loading = false } },
    async reloadFromReview() { if (this.busy || !(await confirmDiscard(this.$t('admin:comments.discardDiscussionPolicyDraft'))) || this.busy) return; this.reviewOpen = false; this.resetPolicy(); await this.reload() },
    async savePolicy() { if (!this.saved || !this.dirty || this.busy || this.issues.length) return; this.saving = true; this.saveError = ''; try { const result = await saveDiscussionWorkspace(this.enabled, discussionSettings(this.draft), this.saved.fingerprint, this.pageRatingsMode, this.pageRatingsEnabled); if (this.disposed) return; this.saved = { ...this.saved, ...result }; this.saving = false; this.resetPolicy(); this.reviewOpen = false; this.notice = result.warnings?.length ? result.warnings.join(' ') : this.$t('admin:comments.discussionPolicySaved'); this.noticeWarning = Boolean(result.warnings?.length); try { const latest = await fetchDiscussionWorkspace(); if (!this.disposed) this.saved = { ...this.saved, counts: latest.counts, runtime: latest.runtime } } catch { if (!this.disposed) { this.notice += ` ${this.$t('admin:comments.runtimeStatusCouldNot')}`; this.noticeWarning = true } } } catch (error) { if (!this.disposed) this.saveError = getErrorMessage(error) } finally { if (!this.disposed) this.saving = false } },
    async loadInventory() { const sequence = ++this.inventorySequence; this.inventoryLoading = true; this.inventoryError = ''; try { const value = await fetchDiscussionInventory(new URLSearchParams({ search: this.search || '', state: this.state, visibility: this.visibility, offset: String(this.offset), limit: '30' })); if (!this.disposed && sequence === this.inventorySequence) this.inventory = value } catch (error) { if (!this.disposed && sequence === this.inventorySequence) this.inventoryError = getErrorMessage(error) } finally { if (!this.disposed && sequence === this.inventorySequence) this.inventoryLoading = false } },
    async openComment(id: number) { if (this.busy) return; const sequence = ++this.detailSequence; this.detailId = id; this.detailOpen = true; this.detailLoading = true; this.detailError = ''; this.actionError = ''; this.detail = null; this.reason = ''; try { const value = await inspectDiscussion(id); if (!this.disposed && sequence === this.detailSequence) this.detail = value } catch (error) { if (!this.disposed && sequence === this.detailSequence) this.detailError = getErrorMessage(error) } finally { if (!this.disposed && sequence === this.detailSequence) this.detailLoading = false } },
    async moderate() { if (!this.detail || this.busy || this.reason.trim().length < 3) return; this.acting = true; this.actionError = ''; try { const value = await moderateDiscussion(this.detail.id, !this.detail.isHidden, this.reason.trim(), this.detail.fingerprint); if (this.disposed) return; this.detail = value; this.reason = ''; this.notice = value.isHidden ? this.$t('admin:comments.commentHiddenReaders') : this.$t('admin:comments.commentRestoredReaders'); this.noticeWarning = false; await this.refreshCounts(); await this.loadInventory() } catch (error) { if (!this.disposed) this.actionError = getErrorMessage(error) } finally { if (!this.disposed) this.acting = false } },
